// src/lib/plattform/geodaten/geo.js
//
// Reine Geometrie-Helfer für das Akquise-Cockpit (Client + Server, ohne Fremdpakete). Koordinaten wie in
// GeoJSON: [lon, lat] in WGS84 (EPSG:4326). Flächen und Abstände werden in einer lokalen, flächentreuen
// Näherung (äquirektangulär um den Mittelpunkt) gerechnet – für Parzellen und Cluster bis einige Kilometer
// ist der Fehler < 0,5 %. Der Geodaten-Dienst rechnet im Betrieb exakt in EPSG:31287 (MGI / Austria Lambert).
// Gegenstück in Python: Backend-Import/dienste/geodaten/geodaten/geometrie.py (gleiche Formeln, gleiche Tests).

export const ERDRADIUS_M = 6371008.8;
const RAD = Math.PI / 180;

/** Großkreisentfernung in Metern zwischen [lon, lat] und [lon, lat] */
export function distanzM(a, b) {
  const dLat = (b[1] - a[1]) * RAD;
  const dLon = (b[0] - a[0]) * RAD;
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(a[1] * RAD) * Math.cos(b[1] * RAD) * Math.sin(dLon / 2) ** 2;
  return 2 * ERDRADIUS_M * Math.asin(Math.min(1, Math.sqrt(h)));
}

/** Projektion [lon, lat] → [x, y] in Metern um einen Bezugspunkt (lokal äquirektangulär) */
export function projektor(bezug) {
  const kx = Math.cos(bezug[1] * RAD) * ERDRADIUS_M * RAD;
  const ky = ERDRADIUS_M * RAD;
  return (p) => [(p[0] - bezug[0]) * kx, (p[1] - bezug[1]) * ky];
}

/** Äußerer Ring eines GeoJSON-Polygons bzw. aller Teile eines MultiPolygons */
export function ringe(geometrie) {
  if (!geometrie) return [];
  if (geometrie.type === "Polygon") return [geometrie.coordinates];
  if (geometrie.type === "MultiPolygon") return geometrie.coordinates;
  return [];
}

function ringFlaeche(ring) {
  let s = 0;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) s += ring[j][0] * ring[i][1] - ring[i][0] * ring[j][1];
  return s / 2;
}

function ringUmfang(ring) {
  let s = 0;
  for (let i = 1; i < ring.length; i++) s += Math.hypot(ring[i][0] - ring[i - 1][0], ring[i][1] - ring[i - 1][1]);
  return s;
}

/** Bounding Box [minLon, minLat, maxLon, maxLat] beliebiger GeoJSON-Geometrie */
export function bbox(geometrie) {
  const b = [Infinity, Infinity, -Infinity, -Infinity];
  const lauf = (c) => {
    if (typeof c[0] === "number") {
      if (c[0] < b[0]) b[0] = c[0];
      if (c[1] < b[1]) b[1] = c[1];
      if (c[0] > b[2]) b[2] = c[0];
      if (c[1] > b[3]) b[3] = c[1];
    } else for (const x of c) lauf(x);
  };
  if (geometrie?.coordinates) lauf(geometrie.coordinates);
  return b;
}

export const bboxSchneidet = (a, b) => a[0] <= b[2] && a[2] >= b[0] && a[1] <= b[3] && a[3] >= b[1];

/** Schwerpunkt (Flächenschwerpunkt des größten Teils; bei Punkten der Punkt) als [lon, lat] */
export function schwerpunkt(geometrie) {
  if (geometrie?.type === "Point") return geometrie.coordinates;
  const teile = ringe(geometrie);
  if (!teile.length) return null;
  let best = null;
  let bestA = -1;
  for (const poly of teile) {
    const ring = poly[0];
    const bb = bbox({ coordinates: ring });
    const bezug = [(bb[0] + bb[2]) / 2, (bb[1] + bb[3]) / 2];
    const p = projektor(bezug);
    const xy = ring.map(p);
    const a = ringFlaeche(xy);
    if (Math.abs(a) <= bestA) continue;
    let cx = 0;
    let cy = 0;
    for (let i = 0, j = xy.length - 1; i < xy.length; j = i++) {
      const f = xy[j][0] * xy[i][1] - xy[i][0] * xy[j][1];
      cx += (xy[j][0] + xy[i][0]) * f;
      cy += (xy[j][1] + xy[i][1]) * f;
    }
    if (a === 0) continue;
    cx /= 6 * a;
    cy /= 6 * a;
    const kx = Math.cos(bezug[1] * RAD) * ERDRADIUS_M * RAD;
    const ky = ERDRADIUS_M * RAD;
    best = [bezug[0] + cx / kx, bezug[1] + cy / ky];
    bestA = Math.abs(a);
  }
  return best;
}

/** Fläche in m² (Außenringe minus Löcher) */
export function flaecheM2(geometrie) {
  const teile = ringe(geometrie);
  if (!teile.length) return 0;
  const bb = bbox(geometrie);
  const p = projektor([(bb[0] + bb[2]) / 2, (bb[1] + bb[3]) / 2]);
  let s = 0;
  for (const poly of teile) {
    poly.forEach((ring, i) => {
      const a = Math.abs(ringFlaeche(ring.map(p)));
      s += i === 0 ? a : -a;
    });
  }
  return Math.max(0, s);
}

/** Umfang in m (nur Außenringe) */
export function umfangM(geometrie) {
  const teile = ringe(geometrie);
  if (!teile.length) return 0;
  const bb = bbox(geometrie);
  const p = projektor([(bb[0] + bb[2]) / 2, (bb[1] + bb[3]) / 2]);
  return teile.reduce((s, poly) => s + ringUmfang(poly[0].map(p)), 0);
}

// src/lib/plattform/geodaten/scoring.js
//
// Scoring-Engine der Flächenakquise (reine Funktionen, Client + Server). Bewertet eine Kandidatenfläche –
// eine Parzelle oder einen zusammenhängenden Verbund mehrerer Parzellen/Schläge – mit 0–100 Punkten und
// Begründung. Gegenstück in Python (identische Regeln und Konstanten, gemeinsame Testfälle):
//   Backend-Import/dienste/geodaten/geodaten/scoring.py  ·  tests/faelle.json
//
// Kriterien (Höchstpunkte): Größe 20 · Form 8 · Neigung/Exposition 12 · Nutzung 8 · Siedlungsabstand 8 ·
// Netz (Trassenlänge) 22 · Netzanschlusskosten 8 · Widmungslage 10 · Einstrahlung 4 = 100.
// Abzüge: Schutzgebiete (Nähe/Überdeckung), knappe Netzkapazität. K.-o.-Kriterien deckeln den Punktwert
// (zu klein, Kern-Schutzgebiet, zu steil).
//
// Netzanschlusskosten: Logik des Netzanschluss-Rechners (src/lib/rechner/netzanschluss.js, FREIFLAECHE.netz).
// Alle Werte sind Schätzungen für die Vorauswahl – maßgeblich sind Netzbetreiber-Auskunft und Standortprüfung.

import { FREIFLAECHE, PACHT } from "../../invest/markt.js";
import { rechneNetzanschluss, ebeneFuer } from "../../rechner/netzanschluss.js";
import { distanzM } from "./geo.js";

export const SCORING_VERSION = "2026-09-30.2"; // .2: Deutschland/Schweiz (EEG-Kulisse, BauGB-Privilegierung, Richtplan, FFF)

export const GEWICHTE = { groesse: 20, form: 8, neigung: 12, nutzung: 8, siedlung: 8, netz: 22, kosten: 8, widmung: 10, einstrahlung: 4 };

/**
 * Gewichte je Land (Summe jeweils 100). Österreich = GEWICHTE. Deutschland und Schweiz erhalten das Kriterium
 * „Flächenkulisse“ (DE: EEG-Förderkulisse § 37 EEG; CH: kantonale Eignungsgebiete/vorbelastete Standorte) – die übrigen
 * Kriterien werden proportional skaliert (Punkte = Grundpunkte × Landesgewicht / Grundgewicht).
 */
export const GEWICHTE_LAND = {
  AT: GEWICHTE,
  DE: { groesse: 18, form: 7, neigung: 10, nutzung: 6, siedlung: 7, netz: 20, kosten: 7, widmung: 8, kulisse: 14, einstrahlung: 3 },
  CH: { groesse: 18, form: 7, neigung: 11, nutzung: 6, siedlung: 7, netz: 20, kosten: 7, widmung: 8, kulisse: 12, einstrahlung: 4 },
};

/**
 * Flächenkulisse (Anteile 0–1 der Kandidatenfläche, aus Geodaten des Dienstes bzw. der Demo):
 *   DE  randstreifenAnteil – ≤ 500 m längs Autobahn/Schienenweg (§ 37 Abs. 1 Nr. 2 lit. c EEG 2023) – förderfähig
 *       benachteiligtAnteil – Acker/Grünland im benachteiligten Gebiet (§ 37 Abs. 1 Nr. 3 lit. h/i, § 37c EEG; Länder-Opt-out möglich)
 *       moorAnteil         – entwässerter, landwirtschaftlich genutzter Moorboden mit Wiedervernässung (§ 37 Abs. 1 Nr. 3 lit. e EEG)
 *       konversionAnteil   – Konversions-/versiegelte Fläche (§ 37 Abs. 1 Nr. 2 lit. a/b EEG)
 *       privilegiertAnteil – ≤ 200 m längs Autobahn/zweigleisiger Hauptbahn (§ 35 Abs. 1 Nr. 8 lit. b BauGB) → Widmungslage
